import { assetUrl } from './asset-url';

// Word families for the word card (decide: decision, decisive...), from
// static/families.json -- generated by scripts/extract-families.mjs from
// WordNet's derivational links; never hand-edit it. Background worker only,
// fetched on the first lookup like the other dictionaries.

let familiesPromise: Promise<Record<string, string[]>> | null = null;

export async function lookupFamily(lemma: string): Promise<string[]> {
  if (lemma.includes(' ')) return []; // merged phrases have no family entry
  if (!familiesPromise) {
    familiesPromise = fetch(assetUrl('families.json')).then((r) => r.json())
      .catch(() => { familiesPromise = null; return {}; });
  }
  const families = await familiesPromise;
  return Object.prototype.hasOwnProperty.call(families, lemma) ? families[lemma] : [];
}
